def match(orders):
    trades = []

    # Books: list of (arrival_time, order_id, side, price, remaining_qty)
    buy_book = []  # sorted by price desc, then arrival_time asc
    sell_book = []  # sorted by price asc, then arrival_time asc

    # Track order ids and their positions for cancellation
    order_map = {}  # order_id -> index in buy_book or sell_book (or None if filled/cancelled)

    arrival_counter = [0]  # counter for arrival times

    def add_to_book(side, order_id, price, qty):
        """Add a limit order to the book"""
        arrival_time = arrival_counter[0]
        arrival_counter[0] += 1

        if side == 'buy':
            buy_book.append([arrival_time, order_id, side, price, qty])
            order_map[order_id] = ('buy', len(buy_book) - 1)
            buy_book.sort(key=lambda x: (-x[3], x[0]))  # sort by price desc, arrival asc
        else:  # sell
            sell_book.append([arrival_time, order_id, side, price, qty])
            order_map[order_id] = ('sell', len(sell_book) - 1)
            sell_book.sort(key=lambda x: (x[3], x[0]))  # sort by price asc, arrival asc

    def update_order_map():
        """Rebuild order_map after sorting"""
        order_map.clear()
        for i, order in enumerate(buy_book):
            order_map[order[1]] = ('buy', i)
        for i, order in enumerate(sell_book):
            order_map[order[1]] = ('sell', i)

    def match_order(side, order_id, price, qty, is_ioc_or_market=False):
        """Match an incoming order against the book"""
        remaining_qty = qty

        if side == 'buy':
            # Match against sell_book (lowest price first, earliest arrival first)
            i = 0
            while i < len(sell_book) and remaining_qty > 0:
                if is_ioc_or_market or sell_book[i][3] <= price:
                    resting = sell_book[i]
                    trade_qty = min(remaining_qty, resting[4])
                    trades.append([order_id, resting[1], resting[3], trade_qty])

                    remaining_qty -= trade_qty
                    resting[4] -= trade_qty

                    if resting[4] == 0:
                        sell_book.pop(i)
                    else:
                        i += 1
                else:
                    break
        else:  # side == 'sell'
            # Match against buy_book (highest price first, earliest arrival first)
            i = 0
            while i < len(buy_book) and remaining_qty > 0:
                if is_ioc_or_market or buy_book[i][3] >= price:
                    resting = buy_book[i]
                    trade_qty = min(remaining_qty, resting[4])
                    trades.append([resting[1], order_id, resting[3], trade_qty])

                    remaining_qty -= trade_qty
                    resting[4] -= trade_qty

                    if resting[4] == 0:
                        buy_book.pop(i)
                    else:
                        i += 1
                else:
                    break

        update_order_map()
        return remaining_qty

    # Process each order
    for order in orders:
        order_type = order[0]

        if order_type == 'limit':
            _, order_id, side, price, qty = order
            remaining_qty = match_order(side, order_id, price, qty, is_ioc_or_market=False)
            if remaining_qty > 0:
                add_to_book(side, order_id, price, remaining_qty)

        elif order_type == 'ioc':
            _, order_id, side, price, qty = order
            match_order(side, order_id, price, qty, is_ioc_or_market=False)

        elif order_type == 'market':
            _, order_id, side, qty = order
            match_order(side, order_id, None, qty, is_ioc_or_market=True)

        elif order_type == 'cancel':
            _, order_id = order
            if order_id in order_map:
                book_side, idx = order_map[order_id]
                if book_side == 'buy':
                    buy_book.pop(idx)
                else:
                    sell_book.pop(idx)
                update_order_map()

    return trades

